window.AUTH=window.AUTH||{};window.AUTH["22-1079"]={"d":"22-1079","id":"2023/22-1079","n":"Truck Insurance Exchange v. Kaiser Gypsum Company, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Truck Insurance Exchange","date":"2023-12-07","url":"https://www.supremecourt.gov/DocketPDF/22/22-1079/292662/20231207144346136_Truck%20Opening%20Brief.pdf","side":"pet","n":68},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-12-14","url":"https://www.supremecourt.gov/DocketPDF/22/22-1079/293403/20231214144945869_22-1079tsacUnited%20States.pdf","side":"us","n":100},{"k":"respondent","label":"Brief of respondents Official Committee of Asbestos Personal Injury Claimants, et al.","date":"2024-01-24","url":"https://www.supremecourt.gov/DocketPDF/22/22-1079/298677/20240124170609899_Claimants%20resp.%20brief.pdf","side":"res","n":55},{"k":"reply","label":"Reply of petitioner Truck Insurance Exchange","date":"2024-02-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-1079/301273/20240223130343667_Truck-Kaiser%20--%20Merits%20Reply%20Brief.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r32_2q24.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"22","1":"29, 30","3":"7"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"0":"41","1":"29","2":"31"}},{"t":"case","label":"Alton Railroad Co. v. United States","cite":"315 U.S. 15","y":1942,"id":"scdb/1941-058","sc":1,"op":1,"by":{"0":"25"}},{"t":"case","label":"Amchem Products, Inc. v. Windsor","cite":"521 U.S. 591","y":1997,"id":"1996/96-270","sc":1,"op":1,"sum":"In resolving the case the Court declined to reach the issue of whether the settlement proceeding was a justiciable case or controversy under Article III because, it held, determination of class certification was logically antecedent to these issues.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"American United Mutual Life Insurance Co. v. City of Avon Park","cite":"311 U.S. 138","y":1940,"id":"scdb/1940-013","sc":1,"sum":"1. A plan for the composition of the debts of a municipality under Chapter IX of the Bankruptcy Act comprised a refunding plan whereby the municipality's fiscal agent (a private corporation) would defray the expenses incident to\"the refunding and would be 'reimbursed therefor and compensated for its services by an assessment of participating bondholders. A stated charge was to be made for each $1000 bond, but the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Bank of America v. City of Miami","cite":"581 U.S. 189","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"0":"19, 27, 42, 43","2":"30"}},{"t":"case","label":"Bank of America National Trust & Savings Ass’n v. 203 North LaSalle Street Partnership","cite":"526 U.S. 434","y":1999,"id":"1998/97-1418","sc":1,"op":1,"sum":"A debtor's prebankruptcy equity holders may not contribute new capital and receive ownership in the debtor's reorganization entity","sumSrc":"Oyez","by":{"0":"3","1":"22","2":"3","3":"9"}},{"t":"case","label":"Baron & Budd, P.C. v. Unsecured Asbestos Claimants Committee","cite":"321 B.R. 147","y":2005,"court":"D.N.J.","url":"https://www.courtlistener.com/c/B.R./321/147/","by":{"0":"45"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21"}},{"t":"case","label":"BNSF v. Loos","cite":"139 S. Ct. 893","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"California Department of Toxic Substances Control v. Jim Dobbas, Inc.","cite":"54 F.4th 1078","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/54/1078/","by":{"0":"33","2":"40"}},{"t":"case","label":"Chicot County v. Sherwood","cite":"148 U.S. 529","y":1893,"id":"scdb/1892-166","sc":1,"sum":"An action will lie in a Circuit Court of the United States in the State of Arkansas at the suit of a citizen of New York, against a county in Arkansas, to recover on bonds and coupons issued by the county to aid in the construction of a railroad and held by the citizen of New York, notwithstanding the provisions in the act of the Legislature of Arkansas of February 27,1879, repealing all laws authorizing counties …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Claiborne-Annapolis Ferry Co. v. United States","cite":"285 U.S. 382","y":1932,"id":"scdb/1931-103","sc":1,"sum":"1. Paragraphs 18, 19 and 20 of § 1 of the Ihterstate Commerce Act, respecting extension and new construction of railroads, are restricted to.carriers engaged in transporting persons or property ininterstate and foreign commerce'and were intended to affect intrastate \"commerce only as that may be incidental to the effective regulation of interstate commerce.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38"}},{"t":"case","label":"Colorado River Water Conservation District v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"580 U.S. 451","y":2017,"id":"2016/15-649","sc":1,"op":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"0":"3, 32, 35","1":"2, 23","2":"3, 23, 36, 39, 43","3":"14, 15, 21"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S 332","y":2006,"url":"https://www.courtlistener.com/c/U.S/547/332/","by":{"0":"26, 38"}},{"t":"case","label":"Davis v. FEC","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Denney v. Deutsche Bank AG","cite":"443 F.3d 253","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/443/253/","by":{"0":"27"}},{"t":"case","label":"Elk Grove Unified School District v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"FEC v. Cruz","cite":"142 S. Ct. 1638","y":2022,"id":"2021/21-12","sc":1,"sum":"Section 304 of the Bipartisan Campaign Reform Act of 2002—which limits the amount of post-election contributions that may be used to repay a candidate who lends money to his own campaign—unconstitutionally burdens core political speech.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32, 33, 36, 38","2":"36"}},{"t":"case","label":"Fidelity Financial Services, Inc. v. Fink","cite":"522 U.S. 211","y":1998,"id":"1997/96-1370","sc":1,"sum":"The Court held that a transfer of a security interest is perfected under section 547(c)(3)(B) on the date that the secured party has completed the steps necessary to perfect its interest, so that a creditor may invoke the enabling loan exception only by satisfying state law perfection requirements within the 20-day period provided by the federal statute.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Florida Department of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"op":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Frothingham v. Mellon","cite":"262 U.S. 447","y":1923,"id":"1900-1940/262us447","sc":1,"sum":"The Court held that the administration of federal statutes \"likely to produce addition taxation to be imposed upon a vast number of taxpayers\" was essentially a matter of public and not of individual concern.","sumSrc":"Oyez","by":{"0":"16, 24, 26","3":"5"}},{"t":"case","label":"Herb’s Welding, Inc. v. Gray","cite":"470 U.S. 414","y":1985,"id":"1984/83-728","sc":1,"sum":"Because respondent's employment was not \"maritime,\" he does not qualify for benefits under the LHWCA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","3":"4"}},{"t":"case","label":"Intel Corp. v. Advanced Micro Devices, Inc.","cite":"542 U.S. 241","y":2004,"id":"2003/02-572","sc":1,"sum":"In a 7-to-1 decision, the Court ruled that just because a foreign tribunal was unwilling to demand certain documents did not mean that it would be unwilling to accept them if provided to them by other means.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"L. Singer & Sons v. Union Pacific Railroad Co.","cite":"311 U.S. 295","y":1940,"id":"scdb/1940-008","sc":1,"op":1,"sum":"(1) That the plaintiffs were without standing to maintain the suit as \"parties in interest\" under paragraph 20, § 402, Transportation Act of 1920. P. 300, et seq. (2) That thie city in which the existing market is located was properly denied leave to intervene as a party plaintiff. P. 305. 109 F. 2d 493, affirmed. CERTIORARI, 309 U. S. 653, to review the affirmance of a decree dismissing a bill praying for an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25","2":"27-28","3":"6"}},{"t":"case","label":"Lexmark International, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"ar":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"2, 19, 39, 41, 42","2":"30-31","3":"6"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"26, 46","1":"31","2":"35-36, 38-39, 41","3":"6"}},{"t":"case","label":"New Orleans Public Service, Inc. v. Council of City of New Orleans","cite":"491 U.S. 350","y":1989,"id":"1988/88-348","sc":1,"sum":"The District Court erred in abstaining from exercising jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Ortiz v. Fibreboard Corp.","cite":"527 U.S. 815","y":1999,"id":"1998/97-1704","sc":1,"sum":"The Court held that \"applicants for contested certification [of a mandatory settlement class on a limited fund theory under Rule 23(b)(1)(B)] must show that the fund is limited by more than the agreement of the parties, and has been allocated to claimants belonging within the class by a process addressing any conflicting interests of class members.\" \"The record on which the District Court rested its certification of the class for the purpose of the global settlement did not support the essential premises of mandatory limited fund actions.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Pepper v. Litton","cite":"308 U.S. 295","y":1939,"id":"scdb/1939-033","sc":1,"by":{"0":"50"}},{"t":"case","label":"Robertson v. Allied Solutions, LLC","cite":"902 F.3d 690","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/902/690/","sum":"Holding that job applicant suffered cognizable injury when prospective employer rescinded her offer after background check, yet unlawfully withheld underlying report and explanation of rights under Fair Credit Reporting Act, 15 U.S.C. §§ 1681-1681x.","sumSrc":"brief:2","by":{"0":"35","2":"38-39"}},{"t":"case","label":"SAS Institute, Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"op":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Schindler Elevator Corp. v. United States ex rel. Kirk","cite":"563 U.S. 401","y":2011,"id":"2010/10-188","sc":1,"sum":"The Court held that a whistleblower may not use information obtained through Freedom of Information Act requests to allege violations of the Federal Claims Act by a government contractor.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Sprint Communications, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"sum":"The Court held that a federal court does not need to abstain from deciding a case only because there is a case in state court that deals with the same subject matter.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 23"}},{"t":"case","label":"Teton Historic Aviation Foundation v. U.S. Department of Defense","cite":"785 F.3d 719","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/785/719/","sum":"Noting undisputed finding that claimant suffered an injury-in-fact from lost opportunity “to compete” for “future” business.","sumSrc":"brief:2","by":{"0":"35","2":"39"}},{"t":"case","label":"Thompson v. North American Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21","2":"35-36, 41"}},{"t":"case","label":"United States Bank National Ass’n v. Village at Lakeridge, LLC","cite":"583 U.S. 387","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/387/","sc":1,"op":1,"by":{"0":"22"}},{"t":"case","label":"United States v. Gonzalez","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"22","1":"29","3":"21"}},{"t":"case","label":"United States v. Key","cite":"397 U.S. 322","y":1970,"id":"1969/402","sc":1,"sum":"The United States is entitled to absolute priority of Tayment under § 3466 of the Revised Statutes over the other claimants in the reorganization here involved, there being no inconsistency between the terms of that section and the provisions of Chapter X. Pp. 324-333. 407 F. 2d 635, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"United States v. Noland","cite":"517 U.S. 535","y":1996,"id":"1995/95-323","sc":1,"sum":"Announced by Justice David H. Souter, the Court ruled that giving tax-penalty claims a lower priority than other claims contradicts Congress_ scheme of priorities regarding federal bankruptcy law.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"United States v. Wong Kim Ark","cite":"169 U.S. 649","y":1898,"id":"1850-1900/169us649","sc":1,"sum":"Because Wong was born in the United States and his parents were not “employed in any diplomatic or official capacity under the Emperor of China,” the Citizenship Clause of the Fourteenth Amendment automatically makes him a U.S. citizen.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Gallardo ex rel. Vassallo v. Marstiller","cite":"596 U.S. 420","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"xi Western Pacific California Railroad Co. v. Southern Pacific Co.","cite":"284 U.S. 47","y":1931,"id":"scdb/1931-021","sc":1,"op":1,"by":{"0":"16, 18, 23, 24, 26, 32","1":"19","2":"26-28","3":"5, 13"}},{"t":"usc","label":"11 U.S.C. § 67","url":"https://www.law.cornell.edu/uscode/text/11/67","by":{"0":"27"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(5)","(10)","(12)","(13)","(16)","(17)","(28)","(29)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"1","1":"1, 1, 2, 20, 2, 20, 3, 20, 2, 2, 20, 20, 20","3":"12, 22"}},{"t":"usc","label":"11 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/11/102","subs":["(3)"],"stext":{"head":"§102. Rules of construction","paras":[[0,"In this title—"],[1,"(1) \"after notice and a hearing\", or a similar phrase—"],[2,"(A) means after such notice as is appropriate in the particular circumstances, and such opportunity for a hearing as is appropriate in the particular circumstances; but"],[2,"(B) authorizes an act without an actual hearing if such notice is given properly and if—"],[3,"(i) such a hearing is not requested timely by a party in interest; or"],[3,"(ii) there is insufficient time for a hearing to be commenced before such act must be done, and the court authorizes such act;"],[1,"(2) \"claim against the debtor\" includes claim against property of the debtor;"],[1,"(3) \"includes\" and \"including\" are not limiting;"],[1,"(4) \"may not\" is prohibitive, and not permissive;"],[1,"(5) \"or\" is not exclusive;"],[1,"(6) \"order for relief\" means entry of an order for relief;"],[1,"(7) the singular includes the plural;"],[1,"(8) a definition, contained in a section of this title that refers to another section of this title, does not, for the purpose of such reference, affect the meaning of a term used in such other section; and"],[1,"(9) \"United States trustee\" includes a designee of the United States trustee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/102?type=usc&year=mostrecent&link-type=html"},"head":"§102. Rules of construction","tname":"Bankruptcy","by":{"0":"21","1":"20","3":"4"}},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","stext":{"head":"§307. United States trustee","paras":[[0,"The United States trustee may raise and may appear and be heard on any issue in any case or proceeding under this title but may not file a plan pursuant to section 1121(c) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/307?type=usc&year=mostrecent&link-type=html"},"head":"§307. United States trustee","tname":"Bankruptcy","by":{"0":"49","1":"1, 18","3":"4"}},{"t":"usc","label":"11 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/11/502","subs":["(a)"],"stext":{"head":"§502. Allowance of claims or interests","paras":[[0,"(a) A claim or interest, proof of which is filed under section 501 of this title, is deemed allowed, unless a party in interest, including a creditor of a general partner in a partnership that is a debtor in a case under chapter 7 of this title, objects."],[0,"(b) Except as provided in subsections (e)(2), (f), (g), (h) and (i) of this section, if such objection to a claim is made, the court, after notice and a hearing, shall determine the amount of such claim in lawful currency of the United States as of the date of the filing of the petition, and shall allow such claim in such amount, except to the extent that—"],[1,"(1) such claim is unenforceable against the debtor and property of the debtor, under any agreement or applicable law for a reason other than because such claim is contingent or unmatured;"],[1,"(2) such claim is for unmatured interest;"],[1,"(3) if such claim is for a tax assessed against property of the estate, such claim exceeds the value of the interest of the estate in such property;"],[1,"(4) if such claim is for services of an insider or attorney of the debtor, such claim exceeds the reasonable value of such services;"],[1,"(5) such claim is for a debt that is unmatured on the date of the filing of the petition and that is excepted from discharge under section 523(a)(5) of this title;"],[1,"(6) if such claim is the claim of a lessor for damages resulting from the termination of a lease of real property, such claim exceeds—"],[2,"(A) the rent reserved by such lease, without acceleration, for the greater of one year, or 15 percent, not to exceed three years, of the remaining term of such lease, following the earlier of—"],[3,"(i) the date of the filing of the petition; and"],[3,"(ii) the date on which such lessor repossessed, or the lessee surrendered, the leased property; plus"],[2,"(B) any unpaid rent due under such lease, without acceleration, on the earlier of such dates;"],[1,"(7) if such claim is the claim of an employee for damages resulting from the termination of an employment contract, such claim exceeds—"],[2,"(A) the compensation provided by such contract, without acceleration, for one year following the earlier of—"],[3,"(i) the date of the filing of the petition; or"],[3,"(ii) the date on which the employer directed the employee to terminate, or such employee terminated, performance under such contract; plus"],[2,"(B) any unpaid compensation due under such contract, without acceleration, on the earlier of such dates;"],[1,"(8) such claim results from a reduction, due to late payment, in the amount of an otherwise applicable credit available to the debtor in connection with an employment tax on wages, salaries, or commissions earned from the debtor; or"],[1,"(9) proof of such claim is not timely filed, except to the extent tardily filed as permitted under paragraph (1), (2), or (3) of section 726(a) or under the Federal Rules of Bankruptcy Procedure, except that—"],[2,"(A) a claim of a governmental unit shall be timely filed if it is filed before 180 days after the date of the order for relief or such later time as the Federal Rules of Bankruptcy Procedure may provide; and"],[2,"(B) in a case under chapter 13, a claim of a governmental unit for a tax with respect to a return filed under section 1308 shall be timely if the claim is filed on or before the date that is 60 days after the date on which such return was filed as required."],[0,"(c) There shall be estimated for purpose of allowance under this section—"],[1,"(1) any contingent or unliquidated claim, the fixing or liquidation of which, as the case may be, would unduly delay the administration of the case; or"],[1,"(2) any right to payment arising from a right to an equitable remedy for breach of performance."],[0,"(d) Notwithstanding subsections (a) and (b) of this section, the court shall disallow any claim of any entity from which property is recoverable under section 542, 543, 550, or 553 of this title or that is a transferee of a transfer avoidable under section 522(f), 522(h), 544, 545, 547, 548, 549, or 724(a) of this title, unless such entity or transferee has paid the amount, or turned over any such property, for which such entity or transferee is liable under section 522(i), 542, 543, 550, or 553 of this title."],[0,"(e)(1) Notwithstanding subsections (a), (b), and (c) of this section and paragraph (2) of this subsection, the court shall disallow any claim for reimbursement or contribution of an entity that is liable with the debtor on or has secured the claim of a creditor, to the extent that—"],[1,"(A) such creditor's claim against the estate is disallowed;"],[1,"(B) such claim for reimbursement or contribution is contingent as of the time of allowance or disallowance of such claim for reimbursement or contribution; or"],[1,"(C) such entity asserts a right of subrogation to the rights of such creditor under section 509 of this title."],[0,"(2) A claim for reimbursement or contribution of such an entity that becomes fixed after the commencement of the case shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section, or disallowed under subsection (d) of this section, the same as if such claim had become fixed before the date of the filing of the petition."],[0,"(f) In an involuntary case, a claim arising in the ordinary course of the debtor's business or financial affairs after the commencement of the case but before the earlier of the appointment of a trustee and the order for relief shall be determined as of the date such claim arises, and shall be allowed under subsection (a), (b), or (c) of this section or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(g)(1) A claim arising from the rejection, under section 365 of this title or under a plan under chapter 9, 11, 12, or 13 of this title, of an executory contract or unexpired lease of the debtor that has not been assumed shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(2) A claim for damages calculated in accordance with section 562 shall be allowed under subsection (a), (b), or (c), or disallowed under subsection (d) or (e), as if such claim had arisen before the date of the filing of the petition."],[0,"(h) A claim arising from the recovery of property under section 522, 550, or 553 of this title shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section, or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(i) A claim that does not arise until after the commencement of the case for a tax entitled to priority under section 507(a)(8) of this title shall be determined, and shall be allowed under subsection (a), (b), or (c) of this section, or disallowed under subsection (d) or (e) of this section, the same as if such claim had arisen before the date of the filing of the petition."],[0,"(j) A claim that has been allowed or disallowed may be reconsidered for cause. A reconsidered claim may be allowed or disallowed according to the equities of the case. Reconsideration of a claim under this subsection does not affect the validity of any payment or transfer from the estate made to a holder of an allowed claim on account of such allowed claim that is not reconsidered, but if a reconsidered claim is allowed and is of the same class as such holder's claim, such holder may not receive any additional payment or transfer from the estate on account of such holder's allowed claim until the holder of such reconsidered and allowed claim receives payment on account of such claim proportionate in value to that already received by such other holder. This subsection does not alter or modify the trustee's right to recover from a creditor any excess payment or transfer made to such creditor."],[0,"(k)(1) The court, on the motion of the debtor and after a hearing, may reduce a claim filed under this section based in whole on an unsecured consumer debt by not more than 20 percent of the claim, if—"],[1,"(A) the claim was filed by a creditor who unreasonably refused to negotiate a reasonable alternative repayment schedule proposed on behalf of the debtor by an approved nonprofit budget and credit counseling agency described in section 111;"],[1,"(B) the offer of the debtor under subparagraph (A)—"],[2,"(i) was made at least 60 days before the date of the filing of the petition; and"],[2,"(ii) provided for payment of at least 60 percent of the amount of the debt over a period not to exceed the repayment period of the loan, or a reasonable extension thereof; and"],[1,"(C) no part of the debt under the alternative repayment schedule is nondischargeable."],[0,"(2) The debtor shall have the burden of proving, by clear and convincing evidence, that—"],[1,"(A) the creditor unreasonably refused to consider the debtor's proposal; and"],[1,"(B) the proposed alternative repayment schedule was made prior to expiration of the 60-day period specified in paragraph (1)(B)(i)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/502?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§502. Allowance of claims or interests","tname":"Bankruptcy","by":{"0":"4","1":"2, 2"}},{"t":"usc","label":"11 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/11/524","subs":["(g)","(g)(1)","(g)(2)","(g)(2)(B)(i)(I)","(g)(2)(B)(i)(II)","(g)(2)(B)(i)(III)","(g)(2)(B)(i)(IV)","(g)(2)(B)(ii)(III)","(g)(2)(B)(ii)(IV)(bb)","(g)(2)(B)(ii)(V)","(g)(4)(B)(i)"],"stext":{"head":"§524. Effect of discharge","paras":[[0,"(a) A discharge in a case under this title—"],[1,"(1) voids any judgment at any time obtained, to the extent that such judgment is a determination of the personal liability of the debtor with respect to any debt discharged under section 727, 944, 1141, 1192, 1228, or 1328 of this title, whether or not discharge of such debt is waived;"],[1,"(2) operates as an injunction against the commencement or continuation of an action, the employment of process, or an act, to collect, recover or offset any such debt as a personal liability of the debtor, whether or not discharge of such debt is waived; and"],[1,"(3) operates as an injunction against the commencement or continuation of an action, the employment of process, or an act, to collect or recover from, or offset against, property of the debtor of the kind specified in section 541(a)(2) of this title that is acquired after the commencement of the case, on account of any allowable community claim, except a community claim that is excepted from discharge under section 523, 1192, 1228(a)(1), or 1328(a)(1), or that would be so excepted, determined in accordance with the provisions of sections 523(c) and 523(d) of this title, in a case concerning the debtor's spouse commenced on the date of the filing of the petition in the case concerning the debtor, whether or not discharge of the debt based on such community claim is waived."],[0,"(b) Subsection (a)(3) of this section does not apply if—"],[1,"(1)(A) the debtor's spouse is a debtor in a case under this title, or a bankrupt or a debtor in a case under the Bankruptcy Act, commenced within six years of the date of the filing of the petition in the case concerning the debtor; and"],[1,"(B) the court does not grant the debtor's spouse a discharge in such case concerning the debtor's spouse; or"],[1,"(2)(A) the court would not grant the debtor's spouse a discharge in a case under chapter 7 of this title concerning such spouse commenced on the date of the filing of the petition in the case concerning the debtor; and"],[1,"(B) a determination that the court would not so grant such discharge is made by the bankruptcy court within the time and in the manner provided for a determination under section 727 of this title of whether a debtor is granted a discharge."],[0,"(c) An agreement between a holder of a claim and the debtor, the consideration for which, in whole or in part, is based on a debt that is dischargeable in a case under this title is enforceable only to any extent enforceable under applicable nonbankruptcy law, whether or not discharge of such debt is waived, only if—"],[1,"(1) such agreement was made before the granting of the discharge under section 727, 1141, 1192, 1228, or 1328 of this title;"],[1,"(2) the debtor received the disclosures described in subsection (k) at or before the time at which the debtor signed the agreement;"],[1,"(3) such agreement has been filed with the court and, if applicable, accompanied by a declaration or an affidavit of the attorney that represented the debtor during the course of negotiating an agreement under this subsection, which states that—"],[2,"(A) such agreement represents a fully informed and voluntary agreement by the debtor;"],[2,"(B) such agreement does not impose an undue hardship on the debtor or a dependent of the debtor; and"],[2,"(C) the attorney fully advised the debtor of the legal effect and consequences of—"],[3,"(i) an agreement of the kind specified in this subsection; and"],[3,"(ii) any default under such an agreement;"],[1,"(4) the debtor has not rescinded such agreement at any time prior to discharge or within sixty days after such agreement is filed with the court, whichever occurs later, by giving notice of rescission to the holder of such claim;"],[1,"(5) the provisions of subsection (d) of this section have been complied with; and"],[1,"(6)(A) in a case concerning an individual who was not represented by an attorney during the course of negotiating an agreement under this subsection, the court approves such agreement as—"],[2,"(i) not imposing an undue hardship on the debtor or a dependent of the debtor; and"],[2,"(ii) in the best interest of the debtor."],[1,"(B) Subparagraph (A) shall not apply to the extent that such debt is a consumer debt secured by real property."],[0,"(d) In a case concerning an individual, when the court has determined whether to grant or not to grant a discharge under section 727, 1141, 1192, 1228, or 1328 of this title, the court may hold a hearing at which the debtor shall appear in person. At any such hearing, the court shall inform the debtor that a discharge has been granted or the reason why a discharge has not been granted. If a discharge has been granted and if the debtor desires to make an agreement of the kind specified in subsection (c) of this section and was not represented by an attorney during the course of negotiating such agreement, then the court shall hold a hearing at which the debtor shall appear in person and at such hearing the court shall—"],[1,"(1) inform the debtor—"],[2,"(A) that such an agreement is not required under this title, under nonbankruptcy law, or under any agreement not made in accordance with the provisions of subsection (c) of this section; and"],[2,"(B) of the legal effect and consequences of—"],[3,"(i) an agreement of the kind specified in subsection (c) of this section; and"],[3,"(ii) a default under such an agreement; and"],[1,"(2) determine whether the agreement that the debtor desires to make complies with the requirements of subsection (c)(6) of this section, if the consideration for such agreement is based in whole or in part on a consumer debt that is not secured by real property of the debtor."],[0,"(e) Except as provided in subsection (a)(3) of this section, discharge of a debt of the debtor does not affect the liability of any other entity on, or the property of any other entity for, such debt."],[0,"(f) Nothing contained in subsection (c) or (d) of this section prevents a debtor from voluntarily repaying any debt."],[0,"(g)(1)(A) After notice and hearing, a court that enters an order confirming a plan of reorganization under chapter 11 may issue, in connection with such order, an injunction in accordance with this subsection to supplement the injunctive effect of a discharge under this section."],[0,"(B) An injunction may be issued under subparagraph (A) to enjoin entities from taking legal action for the purpose of directly or indirectly collecting, recovering, or receiving payment or recovery with respect to any claim or demand that, under a plan of reorganization, is to be paid in whole or in part by a trust described in paragraph (2)(B)(i), except such legal actions as are expressly allowed by the injunction, the confirmation order, or the plan of reorganization."],[0,"(2)(A) Subject to subsection (h), if the requirements of subparagraph (B) are met at the time an injunction described in paragraph (1) is entered, then after entry of such injunction, any proceeding that involves the validity, application, construction, or modification of such injunction, or of this subsection with respect to such injunction, may be commenced only in the district court in which such injunction was entered, and such court shall have exclusive jurisdiction over any such proceeding without regard to the amount in controversy."],[0,"(B) The requirements of this subparagraph are that—"],[1,"(i) the injunction is to be implemented in connection with a trust that, pursuant to the plan of reorganization—"],[2,"(I) is to assume the liabilities of a debtor which at the time of entry of the order for relief has been named as a defendant in personal injury, wrongful death, or property-damage actions seeking recovery for damages allegedly caused by the presence of, or exposure to, asbestos or asbestos-containing products;"],[2,"(II) is to be funded in whole or in part by the securities of 1 or more debtors involved in such plan and by the obligation of such debtor or debtors to make future payments, including dividends;"],[2,"(III) is to own, or by the exercise of rights granted under such plan would be entitled to own if specified contingencies occur, a majority of the voting shares of—"],[3,"(aa) each such debtor;"],[3,"(bb) the parent corporation of each such debtor; or"],[3,"(cc) a subsidiary of each such debtor that is also a debtor; and"],[2,"(IV) is to use its assets or income to pay claims and demands; and"],[1,"(ii) subject to subsection (h), the court determines that—"],[2,"(I) the debtor is likely to be subject to substantial future demands for payment arising out of the same or similar conduct or events that gave rise to the claims that are addressed by the injunction;"],[2,"(II) the actual amounts, numbers, and timing of such future demands cannot be determined;"],[2,"(III) pursuit of such demands outside the procedures prescribed by such plan is likely to threaten the plan's purpose to deal equitably with claims and future demands;"],[2,"(IV) as part of the process of seeking confirmation of such plan—"],[3,"(aa) the terms of the injunction proposed to be issued under paragraph (1)(A), including any provisions barring actions against third parties pursuant to paragraph (4)(A), are set out in such plan and in any disclosure statement supporting the plan; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/524?type=usc&year=mostrecent&link-type=html"},"head":"§524. Effect of discharge","tname":"Bankruptcy","by":{"0":"1, 7, 9, 14, 47","1":"3, 4, 6, 9, 25, 3, 3, 3, 4, 4, 9, 4, 4, 9, 25, 4, 23, 4, 18","3":"1, 9, 14, 15"}},{"t":"usc","label":"11 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/11/1104","stext":{"head":"§1104. Appointment of trustee or examiner","paras":[[0,"(a) At any time after the commencement of the case but before confirmation of a plan, on request of a party in interest or the United States trustee, and after notice and a hearing, the court shall order the appointment of a trustee—"],[1,"(1) for cause, including fraud, dishonesty, incompetence, or gross mismanagement of the affairs of the debtor by current management, either before or after the commencement of the case, or similar cause, but not including the number of holders of securities of the debtor or the amount of assets or liabilities of the debtor; or"],[1,"(2) if such appointment is in the interests of creditors, any equity security holders, and other interests of the estate, without regard to the number of holders of securities of the debtor or the amount of assets or liabilities of the debtor."],[0,"(b)(1) Except as provided in section 1163 of this title, on the request of a party in interest made not later than 30 days after the court orders the appointment of a trustee under subsection (a), the United States trustee shall convene a meeting of creditors for the purpose of electing one disinterested person to serve as trustee in the case. The election of a trustee shall be conducted in the manner provided in subsections (a), (b), and (c) of section 702 of this title."],[0,"(2)(A) If an eligible, disinterested trustee is elected at a meeting of creditors under paragraph (1), the United States trustee shall file a report certifying that election."],[0,"(B) Upon the filing of a report under subparagraph (A)—"],[1,"(i) the trustee elected under paragraph (1) shall be considered to have been selected and appointed for purposes of this section; and"],[1,"(ii) the service of any trustee appointed under subsection (a) shall terminate."],[0,"(C) The court shall resolve any dispute arising out of an election described in subparagraph (A)."],[0,"(c) If the court does not order the appointment of a trustee under this section, then at any time before the confirmation of a plan, on request of a party in interest or the United States trustee, and after notice and a hearing, the court shall order the appointment of an examiner to conduct such an investigation of the debtor as is appropriate, including an investigation of any allegations of fraud, dishonesty, incompetence, misconduct, mismanagement, or irregularity in the management of the affairs of the debtor of or by current or former management of the debtor, if—"],[1,"(1) such appointment is in the interests of creditors, any equity security holders, and other interests of the estate; or"],[1,"(2) the debtor's fixed, liquidated, unsecured debts, other than debts for goods, services, or taxes, or owing to an insider, exceed $5,000,000."],[0,"(d) If the court orders the appointment of a trustee or an examiner, if a trustee or an examiner dies or resigns during the case or is removed under section 324 of this title, or if a trustee fails to qualify under section 322 of this title, then the United States trustee, after consultation with parties in interest, shall appoint, subject to the court's approval, one disinterested person other than the United States trustee to serve as trustee or examiner, as the case may be, in the case."],[0,"(e) The United States trustee shall move for the appointment of a trustee under subsection (a) if there are reasonable grounds to suspect that current members of the governing body of the debtor, the debtor's chief executive or chief financial officer, or members of the governing body who selected the debtor's chief executive or chief financial officer, participated in actual fraud, dishonesty, or criminal conduct in the management of the debtor or the debtor's public financial reporting."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1104?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1104. Appointment of trustee or examiner","tname":"Bankruptcy","by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/11/1105","by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/11/1109","subs":["(a)","(b)"],"stext":{"head":"§1109. Right to be heard","paras":[[0,"(a) The Securities and Exchange Commission may raise and may appear and be heard on any issue in a case under this chapter, but the Securities and Exchange Commission may not appeal from any judgment, order, or decree entered in the case."],[0,"(b) A party in interest, including the debtor, the trustee, a creditors' committee, an equity security holders' committee, a creditor, an equity security holder, or any indenture trustee, may raise and may appear and be heard on any issue in a case under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1109?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1109. Right to be heard","tname":"Bankruptcy","by":{"0":"1, 4, 14, 21, 22, 37, 38, 45, 50","1":"21, 22, 1, 19, 1, 3, 9, 11-16, 20, 21, 25, 27-32","3":"6, 8, 9, 14, 20"}},{"t":"usc","label":"11 U.S.C. § 1121","url":"https://www.law.cornell.edu/uscode/text/11/1121","stext":{"head":"§1121. Who may file a plan","paras":[[0,"(a) The debtor may file a plan with a petition commencing a voluntary case, or at any time in a voluntary case or an involuntary case."],[0,"(b) Except as otherwise provided in this section, only the debtor may file a plan until after 120 days after the date of the order for relief under this chapter."],[0,"(c) Any party in interest, including the debtor, the trustee, a creditors' committee, an equity security holders' committee, a creditor, an equity security holder, or any indenture trustee, may file a plan if and only if—"],[1,"(1) a trustee has been appointed under this chapter;"],[1,"(2) the debtor has not filed a plan before 120 days after the date of the order for relief under this chapter; or"],[1,"(3) the debtor has not filed a plan that has been accepted, before 180 days after the date of the order for relief under this chapter, by each class of claims or interests that is impaired under the plan."],[0,"(d)(1) Subject to paragraph (2), on request of a party in interest made within the respective periods specified in subsections (b) and (c) of this section and after notice and a hearing, the court may for cause reduce or increase the 120-day period or the 180-day period referred to in this section."],[0,"(2)(A) The 120-day period specified in paragraph (1) may not be extended beyond a date that is 18 months after the date of the order for relief under this chapter."],[0,"(B) The 180-day period specified in paragraph (1) may not be extended beyond a date that is 20 months after the date of the order for relief under this chapter."],[0,"(e) In a small business case—"],[1,"(1) only the debtor may file a plan until after 180 days after the date of the order for relief, unless that period is—"],[2,"(A) extended as provided by this subsection, after notice and a hearing; or"],[2,"(B) the court, for cause, orders otherwise;"],[1,"(2) the plan and a disclosure statement (if any) shall be filed not later than 300 days after the date of the order for relief; and"],[1,"(3) the time periods specified in paragraphs (1) and (2), and the time fixed in section 1129(e) within which the plan shall be confirmed, may be extended only if—"],[2,"(A) the debtor, after providing notice to parties in interest (including the United States trustee), demonstrates by a preponderance of the evidence that it is more likely than not that the court will confirm a plan within a reasonable period of time;"],[2,"(B) a new deadline is imposed at the time the extension is granted; and"],[2,"(C) the order extending time is signed before the existing deadline has expired."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1121?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1121. Who may file a plan","tname":"Bankruptcy","by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 1126","url":"https://www.law.cornell.edu/uscode/text/11/1126","stext":{"head":"§1126. Acceptance of plan","paras":[[0,"(a) The holder of a claim or interest allowed under section 502 of this title may accept or reject a plan. If the United States is a creditor or equity security holder, the Secretary of the Treasury may accept or reject the plan on behalf of the United States."],[0,"(b) For the purposes of subsections (c) and (d) of this section, a holder of a claim or interest that has accepted or rejected the plan before the commencement of the case under this title is deemed to have accepted or rejected such plan, as the case may be, if—"],[1,"(1) the solicitation of such acceptance or rejection was in compliance with any applicable nonbankruptcy law, rule, or regulation governing the adequacy of disclosure in connection with such solicitation; or"],[1,"(2) if there is not any such law, rule, or regulation, such acceptance or rejection was solicited after disclosure to such holder of adequate information, as defined in section 1125(a) of this title."],[0,"(c) A class of claims has accepted a plan if such plan has been accepted by creditors, other than any entity designated under subsection (e) of this section, that hold at least two-thirds in amount and more than one-half in number of the allowed claims of such class held by creditors, other than any entity designated under subsection (e) of this section, that have accepted or rejected such plan."],[0,"(d) A class of interests has accepted a plan if such plan has been accepted by holders of such interests, other than any entity designated under subsection (e) of this section, that hold at least two-thirds in amount of the allowed interests of such class held by holders of such interests, other than any entity designated under subsection (e) of this section, that have accepted or rejected such plan."],[0,"(e) On request of a party in interest, and after notice and a hearing, the court may designate any entity whose acceptance or rejection of such plan was not in good faith, or was not solicited or procured in good faith or in accordance with the provisions of this title."],[0,"(f) Notwithstanding any other provision of this section, a class that is not impaired under a plan, and each holder of a claim or interest of such class, are conclusively presumed to have accepted the plan, and solicitation of acceptances with respect to such class from the holders of claims or interests of such class is not required."],[0,"(g) Notwithstanding any other provision of this section, a class is deemed not to have accepted a plan if such plan provides that the claims or interests of such class do not entitle the holders of such claims or interests to receive or retain any property under the plan on account of such claims or interests."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1126?type=usc&year=mostrecent&link-type=html"},"head":"§1126. Acceptance of plan","tname":"Bankruptcy","by":{"0":"7","3":"22, 23"}},{"t":"usc","label":"11 U.S.C. § 1128","url":"https://www.law.cornell.edu/uscode/text/11/1128","subs":["(b)"],"by":{"0":"4","1":"3"}},{"t":"usc","label":"11 U.S.C. § 1129","url":"https://www.law.cornell.edu/uscode/text/11/1129","subs":["(a)(1)","(a)(3)","(a)(11)"],"stext":{"head":"§1129. Confirmation of plan","paras":[[0,"(a) The court shall confirm a plan only if all of the following requirements are met:"],[1,"(1) The plan complies with the applicable provisions of this title."],[1,"(2) The proponent of the plan complies with the applicable provisions of this title."],[1,"(3) The plan has been proposed in good faith and not by any means forbidden by law."],[1,"(4) Any payment made or to be made by the proponent, by the debtor, or by a person issuing securities or acquiring property under the plan, for services or for costs and expenses in or in connection with the case, or in connection with the plan and incident to the case, has been approved by, or is subject to the approval of, the court as reasonable."],[1,"(5)(A)(i) The proponent of the plan has disclosed the identity and affiliations of any individual proposed to serve, after confirmation of the plan, as a director, officer, or voting trustee of the debtor, an affiliate of the debtor participating in a joint plan with the debtor, or a successor to the debtor under the plan; and"],[1,"(ii) the appointment to, or continuance in, such office of such individual, is consistent with the interests of creditors and equity security holders and with public policy; and"],[1,"(B) the proponent of the plan has disclosed the identity of any insider that will be employed or retained by the reorganized debtor, and the nature of any compensation for such insider."],[1,"(6) Any governmental regulatory commission with jurisdiction, after confirmation of the plan, over the rates of the debtor has approved any rate change provided for in the plan, or such rate change is expressly conditioned on such approval."],[1,"(7) With respect to each impaired class of claims or interests—"],[2,"(A) each holder of a claim or interest of such class—"],[3,"(i) has accepted the plan; or"],[3,"(ii) will receive or retain under the plan on account of such claim or interest property of a value, as of the effective date of the plan, that is not less than the amount that such holder would so receive or retain if the debtor were liquidated under chapter 7 of this title on such date; or"],[2,"(B) if section 1111(b)(2) of this title applies to the claims of such class, each holder of a claim of such class will receive or retain under the plan on account of such claim property of a value, as of the effective date of the plan, that is not less than the value of such holder's interest in the estate's interest in the property that secures such claims."],[1,"(8) With respect to each class of claims or interests—"],[2,"(A) such class has accepted the plan; or"],[2,"(B) such class is not impaired under the plan."],[1,"(9) Except to the extent that the holder of a particular claim has agreed to a different treatment of such claim, the plan provides that—"],[2,"(A) with respect to a claim of a kind specified in section 507(a)(2) or 507(a)(3) of this title, on the effective date of the plan, the holder of such claim will receive on account of such claim cash equal to the allowed amount of such claim;"],[2,"(B) with respect to a class of claims of a kind specified in section 507(a)(1), 507(a)(4), 507(a)(5), 507(a)(6), or 507(a)(7) of this title, each holder of a claim of such class will receive—"],[3,"(i) if such class has accepted the plan, deferred cash payments of a value, as of the effective date of the plan, equal to the allowed amount of such claim; or"],[3,"(ii) if such class has not accepted the plan, cash on the effective date of the plan equal to the allowed amount of such claim;"],[2,"(C) with respect to a claim of a kind specified in section 507(a)(8) of this title, the holder of such claim will receive on account of such claim regular installment payments in cash—"],[3,"(i) of a total value, as of the effective date of the plan, equal to the allowed amount of such claim;"],[3,"(ii) over a period ending not later than 5 years after the date of the order for relief under section 301, 302, or 303; and"],[3,"(iii) in a manner not less favorable than the most favored nonpriority unsecured claim provided for by the plan (other than cash payments made to a class of creditors under section 1122(b)); and"],[2,"(D) with respect to a secured claim which would otherwise meet the description of an unsecured claim of a governmental unit under section 507(a)(8), but for the secured status of that claim, the holder of that claim will receive on account of that claim, cash payments, in the same manner and over the same period, as prescribed in subparagraph (C)."],[1,"(10) If a class of claims is impaired under the plan, at least one class of claims that is impaired under the plan has accepted the plan, determined without including any acceptance of the plan by any insider."],[1,"(11) Confirmation of the plan is not likely to be followed by the liquidation, or the need for further financial reorganization, of the debtor or any successor to the debtor under the plan, unless such liquidation or reorganization is proposed in the plan."],[1,"(12) All fees payable under section 1930 of title 28, as determined by the court at the hearing on confirmation of the plan, have been paid or the plan provides for the payment of all such fees on the effective date of the plan."],[1,"(13) The plan provides for the continuation after its effective date of payment of all retiree benefits, as that term is defined in section 1114 of this title, at the level established pursuant to subsection (e)(1)(B) or (g) of section 1114 of this title, at any time prior to confirmation of the plan, for the duration of the period the debtor has obligated itself to provide such benefits."],[1,"(14) If the debtor is required by a judicial or administrative order, or by statute, to pay a domestic support obligation, the debtor has paid all amounts payable under such order or such statute for such obligation that first become payable after the date of the filing of the petition."],[1,"(15) In a case in which the debtor is an individual and in which the holder of an allowed unsecured claim objects to the confirmation of the plan—"],[2,"(A) the value, as of the effective date of the plan, of the property to be distributed under the plan on account of such claim is not less than the amount of such claim; or"],[2,"(B) the value of the property to be distributed under the plan is not less than the projected disposable income of the debtor (as defined in section 1325(b)(2)) to be received during the 5-year period beginning on the date that the first payment is due under the plan, or during the period for which the plan provides payments, whichever is longer."],[1,"(16) All transfers of property under the plan shall be made in accordance with any applicable provisions of nonbankruptcy law that govern the transfer of property by a corporation or trust that is not a moneyed, business, or commercial corporation or trust."],[0,"(b)(1) Notwithstanding section 510(a) of this title, if all of the applicable requirements of subsection (a) of this section other than paragraph (8) are met with respect to a plan, the court, on request of the proponent of the plan, shall confirm the plan notwithstanding the requirements of such paragraph if the plan does not discriminate unfairly, and is fair and equitable, with respect to each class of claims or interests that is impaired under, and has not accepted, the plan."],[0,"(2) For the purpose of this subsection, the condition that a plan be fair and equitable with respect to a class includes the following requirements:"],[1,"(A) With respect to a class of secured claims, the plan provides—"],[2,"(i)(I) that the holders of such claims retain the liens securing such claims, whether the property subject to such liens is retained by the debtor or transferred to another entity, to the extent of the allowed amount of such claims; and"],[2,"(II) that each holder of a claim of such class receive on account of such claim deferred cash payments totaling at least the allowed amount of such claim, of a value, as of the effective date of the plan, of at least the value of such holder's interest in the estate's interest in such property;"],[2,"(ii) for the sale, subject to section 363(k) of this title, of any property that is subject to the liens securing such claims, free and clear of such liens, with such liens to attach to the proceeds of such sale, and the treatment of such liens on proceeds under clause (i) or (iii) of this subparagraph; or"],[2,"(iii) for the realization by such holders of the indubitable equivalent of such claims."],[1,"(B) With respect to a class of unsecured claims—"],[2,"(i) the plan provides that each holder of a claim of such class receive or retain on account of such claim property of a value, as of the effective date of the plan, equal to the allowed amount of such claim; or"],[2,"(ii) the holder of any claim or interest that is junior to the claims of such class will not receive or retain under the plan on account of such junior claim or interest any property, except that in a case in which the debtor is an individual, the debtor may retain property included in the estate under section 1115, subject to the requirements of subsection (a)(14) of this section."],[1,"(C) With respect to a class of interests—"],[2,"(i) the plan provides that each holder of an interest of such class receive or retain on account of such interest property of a value, as of the effective date of the plan, equal to the greatest of the allowed amount of any fixed liquidation preference to which such holder is entitled, any fixed redemption price to which such holder is entitled, or the value of such interest; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1129?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1129. Confirmation of plan","tname":"Bankruptcy","by":{"0":"4, 7, 14, 20, 46, 50","1":"2, 21, 9, 24, 25","3":"9, 15, 22"}},{"t":"usc","label":"11 U.S.C. § 1174","url":"https://www.law.cornell.edu/uscode/text/11/1174","by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 1183","url":"https://www.law.cornell.edu/uscode/text/11/1183","by":{"0":"4"}},{"t":"usc","label":"11 U.S.C. § 1185","url":"https://www.law.cornell.edu/uscode/text/11/1185","by":{"0":"4"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","by":{"0":"27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/2549","by":{"0":"30"}},{"t":"case","label":"Arizona State Legislature v. Arizona Indep. Redistricting Comm’n","cite":"576 U.S. 787","y":2015,"id":"2014/13-1314","sc":1,"sum":"The Court determined that the Elections Clause of the U.S. Constitution does not prohibit a state from creating an independent redistricting commission by initiative.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Begier v. IRS","cite":"496 U.S. 53","y":1990,"id":"1989/89-393","sc":1,"sum":"AIA's trust-fund tax payments from its general accounts were transfers of property held in trust and therefore cannot be avoided as preferences.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"(III) Cases—Continued: Bond v. United States","cite":"564 U.S. 211","y":2011,"id":"2010/09-1227","sc":1,"sum":"The Court held that a defendant, convicted under a federal statute, has a right to challenge his/her conviction based on the unconstitutionality of the statute.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Bullard v. Blue Hills Bank","cite":"575 U.S. 496","y":2015,"id":"2014/14-116","sc":1,"sum":"The Court held that a bankruptcy court’s order denying confirmation of a repayment plan is not a final order for the purpose of immediate appeal.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Central Va. Community Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"1":"2, 17"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"ar":4,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"1":"31","2":"36, 40"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"1":"31","2":"35, 43"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Mission Prod. Holdings, Inc. v. Tempnology, LLC","cite":"139 S. Ct. 1652","y":2019,"id":"2018/17-1657","sc":1,"ar":1,"sum":"A bankruptcy debtor’s rejection of an executory contract under 11 U. S. C. §365 has the same effect as a breach of that contract outside bankruptcy; such an act thus cannot rescind rights that the contract previously granted.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Ritzen Grp., Inc. v. Jackson Masonry, LLC","cite":"140 S. Ct. 582","y":2020,"id":"2019/18-938","sc":1,"sum":"The Court held that a bankruptcy court’s order unreservedly denying relief from the automatic stay of creditor debt-collection efforts outside the bankruptcy forum is final and immediately appealable.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"SEC v. United States Realty & Improvement Co.","cite":"310 U.S. 434","y":1940,"id":"scdb/1939-040","sc":1,"sum":"1. A bankruptcy court has jurisdiction to make orders not subject to collateral attack in a proceeding for an \"arrangement\" with unsecured creditors brought by a debtor corporation under Chapter XI of the Chandler Act, although the financial and corporate setup of the debtor are such that adequate protection and relief can not be obtained under the limitations of that chapter but require a reorganization under …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Seila Law LLC v. Consumer Fin. Prot. Bureau","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Stellwagen v. Clum","cite":"245 U.S. 605","y":1918,"id":"scdb/1917-183","sc":1,"sum":"The Bankruptcy. Act as it was on the dates herein mentioned (February 2,1910, November 9,1910) did not operate to suspend § 6343 of the Revised Statutes of Ohio as it stood February 2, 1910, or the sections into which that section was divided and numbered by the General Code of Ohio, approved February 15, 1910, viz: §§ 11102-11105, as such sections existed May 5,1910.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Summers v. Earth Island Inst.","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"1":"32","2":"38"}},{"t":"case","label":"United Student Aid Funds, Inc. v. Espinosa","cite":"559 U.S. 260","y":2010,"id":"2009/08-1134","sc":1,"sum":"The Court held that Chapter 13 bankruptcy plans which discharge student loans are not void if the debtor fails to provide evidence of \"undue hardship\" in an adversary proceeding.","sumSrc":"Oyez","by":{"1":"21, 30","3":"3, 9, 23"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2020,"id":"2021/20-1530","sc":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"12, 15, 20, 29, 31, 32","2":"2-4, 19-20, 30-31, 35-36, 38, 40-45"}},{"t":"usc","label":"11 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/11/207","subs":["(1934)","(b)(1934)","(c)(1934)"],"op":1,"tname":"Bankruptcy","by":{"1":"26, 26, 26"}},{"t":"usc","label":"11 U.S.C. § 516","url":"https://www.law.cornell.edu/uscode/text/11/516","subs":["(1)(1940)","(1)(1976)"],"by":{"1":"27, 14, 26, 27"}},{"t":"usc","label":"11 U.S.C. § 596","url":"https://www.law.cornell.edu/uscode/text/11/596","subs":["(1940)"],"by":{"1":"27"}},{"t":"usc","label":"11 U.S.C. § 606","url":"https://www.law.cornell.edu/uscode/text/11/606","subs":["(1940)","(1976)"],"op":1,"tname":"Bankruptcy","by":{"1":"26, 14, 27"}},{"t":"usc","label":"11 U.S.C. § 607","url":"https://www.law.cornell.edu/uscode/text/11/607","subs":["(1940)","(1976)"],"by":{"1":"27, 27"}},{"t":"usc","label":"11 U.S.C. § 625","url":"https://www.law.cornell.edu/uscode/text/11/625","subs":["(1940)","(1976)"],"by":{"1":"27, 27"}},{"t":"usc","label":"11 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/11/103","subs":["(g)"],"by":{"1":"21"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"1":"1, 18"}},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","stext":{"head":"§365. Executory contracts and unexpired leases","paras":[[0,"(a) Except as provided in sections 765 and 766 of this title and in subsections (b), (c), and (d) of this section, the trustee, subject to the court's approval, may assume or reject any executory contract or unexpired lease of the debtor."],[0,"(b)(1) If there has been a default in an executory contract or unexpired lease of the debtor, the trustee may not assume such contract or lease unless, at the time of assumption of such contract or lease, the trustee—"],[1,"(A) cures, or provides adequate assurance that the trustee will promptly cure, such default other than a default that is a breach of a provision relating to the satisfaction of any provision (other than a penalty rate or penalty provision) relating to a default arising from any failure to perform nonmonetary obligations under an unexpired lease of real property, if it is impossible for the trustee to cure such default by performing nonmonetary acts at and after the time of assumption, except that if such default arises from a failure to operate in accordance with a nonresidential real property lease, then such default shall be cured by performance at and after the time of assumption in accordance with such lease, and pecuniary losses resulting from such default shall be compensated in accordance with the provisions of this paragraph;"],[1,"(B) compensates, or provides adequate assurance that the trustee will promptly compensate, a party other than the debtor to such contract or lease, for any actual pecuniary loss to such party resulting from such default; and"],[1,"(C) provides adequate assurance of future performance under such contract or lease."],[0,"(2) Paragraph (1) of this subsection does not apply to a default that is a breach of a provision relating to—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title;"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement; or"],[1,"(D) the satisfaction of any penalty rate or penalty provision relating to a default arising from any failure by the debtor to perform nonmonetary obligations under the executory contract or unexpired lease."],[0,"(3) For the purposes of paragraph (1) of this subsection and paragraph (2)(B) of subsection (f), adequate assurance of future performance of a lease of real property in a shopping center includes adequate assurance—"],[1,"(A) of the source of rent and other consideration due under such lease, and in the case of an assignment, that the financial condition and operating performance of the proposed assignee and its guarantors, if any, shall be similar to the financial condition and operating performance of the debtor and its guarantors, if any, as of the time the debtor became the lessee under the lease;"],[1,"(B) that any percentage rent due under such lease will not decline substantially;"],[1,"(C) that assumption or assignment of such lease is subject to all the provisions thereof, including (but not limited to) provisions such as a radius, location, use, or exclusivity provision, and will not breach any such provision contained in any other lease, financing agreement, or master agreement relating to such shopping center; and"],[1,"(D) that assumption or assignment of such lease will not disrupt any tenant mix or balance in such shopping center."],[0,"(4) Notwithstanding any other provision of this section, if there has been a default in an unexpired lease of the debtor, other than a default of a kind specified in paragraph (2) of this subsection, the trustee may not require a lessor to provide services or supplies incidental to such lease before assumption of such lease unless the lessor is compensated under the terms of such lease for any services and supplies provided under such lease before assumption of such lease."],[0,"(c) The trustee may not assume or assign any executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(1)(A) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to an entity other than the debtor or the debtor in possession, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"],[1,"(B) such party does not consent to such assumption or assignment; or"],[1,"(2) such contract is a contract to make a loan, or extend other debt financing or financial accommodations, to or for the benefit of the debtor, or to issue a security of the debtor; or"],[1,"(3) such lease is of nonresidential real property and has been terminated under applicable nonbankruptcy law prior to the order for relief."],[0,"(d)(1) In a case under chapter 7 of this title, if the trustee does not assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor within 60 days after the order for relief, or within such additional time as the court, for cause, within such 60-day period, fixes, then such contract or lease is deemed rejected."],[0,"(2) In a case under chapter 9, 11, 12, or 13 of this title, the trustee may assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor at any time before the confirmation of a plan but the court, on the request of any party to such contract or lease, may order the trustee to determine within a specified period of time whether to assume or reject such contract or lease."],[0,"(3) The trustee shall timely perform all the obligations of the debtor, except those specified in section 365(b)(2), arising from and after the order for relief under any unexpired lease of nonresidential real property, until such lease is assumed or rejected, notwithstanding section 503(b)(1) of this title. The court may extend, for cause, the time for performance of any such obligation that arises within 60 days after the date of the order for relief, but the time for performance shall not be extended beyond such 60-day period. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f) of this section. Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(4)(A) Subject to subparagraph (B), an unexpired lease of nonresidential real property under which the debtor is the lessee shall be deemed rejected, and the trustee shall immediately surrender that nonresidential real property to the lessor, if the trustee does not assume or reject the unexpired lease by the earlier of—"],[1,"(i) the date that is 120 days after the date of the order for relief; or"],[1,"(ii) the date of the entry of an order confirming a plan."],[0,"(B)(i) The court may extend the period determined under subparagraph (A), prior to the expiration of the 120-day period, for 90 days on the motion of the trustee or lessor for cause."],[0,"(ii) If the court grants an extension under clause (i), the court may grant a subsequent extension only upon prior written consent of the lessor in each instance."],[0,"(5) The trustee shall timely perform all of the obligations of the debtor, except those specified in section 365(b)(2), first arising from or after 60 days after the order for relief in a case under chapter 11 of this title under an unexpired lease of personal property (other than personal property leased to an individual primarily for personal, family, or household purposes), until such lease is assumed or rejected notwithstanding section 503(b)(1) of this title, unless the court, after notice and a hearing and based on the equities of the case, orders otherwise with respect to the obligations or timely performance thereof. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f). Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(e)(1) Notwithstanding a provision in an executory contract or unexpired lease, or in applicable law, an executory contract or unexpired lease of the debtor may not be terminated or modified, and any right or obligation under such contract or lease may not be terminated or modified, at any time after the commencement of the case solely because of a provision in such contract or lease that is conditioned on—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title; or"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement."],[0,"(2) Paragraph (1) of this subsection does not apply to an executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(A)(i) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to the trustee or to an assignee of such contract or lease, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/365?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§365. Executory contracts and unexpired leases","tname":"Bankruptcy","by":{"1":"18, 21"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","subs":["(a)"],"by":{"1":"2, 20, 2, 20"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(a)(1)"],"by":{"1":"2"}},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)(1)"],"by":{"1":"18"}},{"t":"usc","label":"11 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/11/557","subs":["(e)(2)"],"by":{"1":"1, 19"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"1":"1, 19"}},{"t":"usc","label":"11 U.S.C. § 762","url":"https://www.law.cornell.edu/uscode/text/11/762","subs":["(b)"],"by":{"1":"1, 19"}},{"t":"usc","label":"11 U.S.C. § 784","url":"https://www.law.cornell.edu/uscode/text/11/784","by":{"1":"1, 19"}},{"t":"usc","label":"11 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/11/901","subs":["(a)"],"by":{"1":"21, 21"}},{"t":"usc","label":"11 U.S.C. § 943","url":"https://www.law.cornell.edu/uscode/text/11/943","subs":["(b)(1)"],"by":{"1":"21"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"1":"1, 2, 6, 13, 15, 16, 21-23, 28, 31"}},{"t":"usc","label":"11 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/11/1102","subs":["(b)(3)"],"by":{"1":"20"}},{"t":"usc","label":"11 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/11/1103","subs":["(c)","(c)(5)"],"by":{"1":"20, 20"}},{"t":"usc","label":"11 U.S.C. § 1122","url":"https://www.law.cornell.edu/uscode/text/11/1122","by":{"1":"2"}},{"t":"usc","label":"11 U.S.C. § 1123","url":"https://www.law.cornell.edu/uscode/text/11/1123","subs":["(b)(2)"],"by":{"1":"2, 18, 21","3":"22"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(1)"],"by":{"1":"3"}},{"t":"usc","label":"11 U.S.C. § 1164","url":"https://www.law.cornell.edu/uscode/text/11/1164","by":{"1":"1, 19"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"1":"22"}},{"t":"usc","label":"11 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/11/1325","subs":["(a)(1)"],"by":{"1":"22"}},{"t":"usc","label":"49 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/49/1","subs":["(20)(1925)","(20)(1970)"],"tname":"Transportation","by":{"1":"20, 20","2":"26"}},{"t":"usc","label":"28 U.S.C. § 517","url":"https://www.law.cornell.edu/uscode/text/28/517","by":{"1":"19"}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","subs":["(a)","(b)"],"by":{"1":"32, 32","3":"12"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"42"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"42"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Holmes v. Securities Inv. Prot. Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29, 31"}},{"t":"case","label":"Hunstein v. Preferred Collection & Mgmt. Servs., Inc.","cite":"48 F.4th 1236","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/1236/","sum":"Holding that a party made “no worse off ” by an action has no right to object to it.","sumSrc":"brief:2","by":{"2":"39"}},{"t":"case","label":"Kiviti v. Bhatt","cite":"80 F.4th 520","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/520/","sum":"Holding that Article III mootness principles do not apply in bankruptcy courts.","sumSrc":"brief:2","by":{"2":"44"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"op":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"London Mkt. Insurers v. Superior Court","cite":"53 Cal. Rptr. 3d 154","y":2007,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr.%203d/53/154/","by":{"2":"11-12"}},{"t":"case","label":"Marrama v. Citizens Bank of Massachusetts","cite":"549 U.S. 365","y":2007,"id":"2006/05-996","sc":1,"sum":"The Court ruled that there is a \"bad faith\" exception to the right of conversion in Section 706(a). The opinion by Justice John Paul Stevens held that although the vast majority of Chapter 7 debtors can convert to Chapter 13, a Chapter 7 debtor who engages in bad faith conduct does not qualify as a \"debtor\" under Chapter 13 and thus cannot convert his petition.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Mt. McKinley Ins. Co. v. Pittsburgh Corning Corp.","cite":"2015 WL 4773425","y":2015,"court":"W.D. Pa. Aug. 12","by":{"2":"10"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Simon v. Eastern Kentucky Welfare Rts. Org.","cite":"426 U.S. 26","y":1976,"id":"1975/74-1124","sc":1,"sum":"The District Court should have granted petitioners' motion to dismiss because respondents failed to establish their standing to bring this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"2":"38-39, 43"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"SuVicMon Dev., Inc. v. Morrison","cite":"991 F.3d 1213","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/991/1213/","by":{"2":"25"}},{"t":"case","label":"Toibb v. Radloff","cite":"501 U.S. 157","y":1991,"id":"1990/90-368","sc":1,"sum":"The Bankruptcy Code's plain language permits individual debtors not engaged in business to file for relief under Chapter 11. Toibb is a debtor within the meaning of § 109(d), which provides that \"a person who may be a debtor under chapter 7... except a stockbroker or a commodity broker, and a railroad may be a debtor under chapter 11.\" He is a person who may be a Chapter 7 debtor, since only railroads and various …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Town of Chester v. Laroe Ests., Inc.","cite":"581 U.S. 433","y":2017,"id":"2016/16-605","sc":1,"sum":"The Court determined that an intervenor to a lawsuit must meet the requirements of Article III standing if the intervenor wishes to pursue relief that was not already requested by the plaintiff.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Cement","cite":"2022 WL 71771","y":2022,"court":"Jan. 7","by":{"2":"12"}},{"t":"case","label":"U.S. Dep’t of Treasury v. Fabe","cite":"508 U.S. 491","y":1993,"id":"1992/91-1513","sc":1,"sum":"In proceedings under Ohio law to liquidate an insolvent insurance company, the United States asserted that its claims as obligee on various of the company's surety bonds were entitled to first priority under 31 U. S. C. §3713(a)(1)(A)(iii). Respondent Fabe, the liquidator appointed by the state court, brought a declaratory judgment action in the Federal District Court to establish that priority in such proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"United States v. $8,440,190.00 in U.S. Currency","cite":"719 F.3d 49","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/719/49/","by":{"2":"43-44"}},{"t":"case","label":"United States v. Cambio Exacto, S.A.","cite":"166 F.3d 522","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/166/522/","by":{"2":"44"}},{"t":"case","label":"United States v. South-Eastern Underwriters Ass’n","cite":"322 U.S. 533","y":1944,"id":"scdb/1943-039","sc":1,"sum":"1. A fire insurance company which conducts a substantial part of its business transactions across state lines is engaged in \"commerce among the several States\" and subject to regulation by Congress under the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Wendt v. 24 Hour Fitness USA, Inc.","cite":"821 F.3d 547","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/547/","sum":"Holding that party cannot pursue claim in order to seek “windfall”.","sumSrc":"brief:2","by":{"2":"39"}},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"sum":"Whitmore lacks standing to proceed in this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"law","label":"Pub. L. No. 103-394","url":"https://www.govinfo.gov/link/statute/108/4106","by":{"2":"7"}},{"t":"usc","label":"15 U.S.C. § 16811681x","url":"https://www.law.cornell.edu/uscode/text/15/16811681x","by":{"2":"39"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","by":{"2":"30"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)(1)"],"by":{"2":"30"}},{"t":"usc","label":"15 U.S.C. § 1011","url":"https://www.law.cornell.edu/uscode/text/15/1011","by":{"2":"6, 6"}},{"t":"usc","label":"18 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/18/152","by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","subs":["(b)(1)"],"by":{"2":"4"}},{"t":"rule","label":"Fed. R. Civ. P. 24","url":"https://www.law.cornell.edu/rules/frcp/rule_24","by":{"2":"5"}},{"t":"case","label":"Alaska Airlines, Inc. v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"21"}},{"t":"case","label":"Arthur Andersen LLP v. Carlisle","cite":"556 U.S. 624","y":2009,"id":"2008/08-146","sc":1,"op":1,"sum":"The Court found that regardless of whether the petitioner is eligible for a stay, a federal court of appeals has jurisdiction over a motion to stay under Section 16(a)(1) of the Federal Arbitration Act.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"ASARCO Inc. v. Kadish","cite":"490 U.S. 605","y":1989,"id":"1988/87-1661","sc":1,"sum":"The judgment is affirmed. 155 Ariz. 484, 747 P. 2d 1183, affirmed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts I, II-A, II-B-2, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"FEC v. Cruz","cite":"596 U.S. 289","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/289/","sc":1,"by":{"3":"5, 21"}},{"t":"case","label":"Jama v. Immigration and Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Pennsylvania Department of Corrections v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Raleigh v. Illinois Department of Revenue","cite":"530 U.S. 15","y":2000,"id":"1999/99-387","sc":1,"sum":"The Court held that \"[w]hen the substantive law creating a tax obligation puts the burden of proof on a taxpayer, the burden of proof on the tax claim in bankruptcy court remains where the substantive law put it (in this case, on the trustee in bankruptcy).\" The Court concluded that the bankruptcy estate's obligation to the Department was established by the state's tax code and that the Bankruptcy Code made no provision for altering the burden on a tax claim, and its silence said that no change was intended.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"Reno v. Catholic Social Services, Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Tennessee Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"sum":"Instead, the Court ruled that discharging a debt owed to a state in a bankruptcy procedure is different from a suit and therefore not barred by sovereign immunity. \"A bankruptcy court is able to provide the debtor a fresh start in this manner ... because the court's jurisdiction is premised on the debtor and his estate, and not on the creditors,\" wrote the Court.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"United States v. Rodgers","cite":"466 U.S. 475","y":1984,"id":"1983/83-620","sc":1,"sum":"The language of § 1001 clearly encompasses criminal investigations conducted by the FBI and Secret Service, and nothing in the legislative history indicates that Congress intended a more restrictive reach for the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","stext":{"head":"§105. Power of court","paras":[[0,"(a) The court may issue any order, process, or judgment that is necessary or appropriate to carry out the provisions of this title. No provision of this title providing for the raising of an issue by a party in interest shall be construed to preclude the court from, sua sponte, taking any action or making any determination necessary or appropriate to enforce or implement court orders or rules, or to prevent an abuse of process."],[0,"(b) Notwithstanding subsection (a) of this section, a court may not appoint a receiver in a case under this title."],[0,"(c) The ability of any district judge or other officer or employee of a district court to exercise any of the authority or responsibilities conferred upon the court under this title shall be determined by reference to the provisions relating to such judge, officer, or employee set forth in title 28. This subsection shall not be interpreted to exclude bankruptcy judges and other officers or employees appointed pursuant to chapter 6 of title 28 from its operation."],[0,"(d) The court, on its own motion or on the request of a party in interest—"],[1,"(1) shall hold such status conferences as are necessary to further the expeditious and economical resolution of the case; and"],[1,"(2) unless inconsistent with another provision of this title or with applicable Federal Rules of Bankruptcy Procedure, may issue an order at any such conference prescribing such limitations and conditions as the court deems appropriate to ensure that the case is handled expeditiously and economically, including an order that—"],[2,"(A) sets the date by which the trustee must assume or reject an executory contract or unexpired lease; or"],[2,"(B) in a case under chapter 11 of this title—"],[3,"(i) sets a date by which the debtor, or trustee if one has been appointed, shall file a disclosure statement and plan;"],[3,"(ii) sets a date by which the debtor, or trustee if one has been appointed, shall solicit acceptances of a plan;"],[3,"(iii) sets the date by which a party in interest other than a debtor may file a plan;"],[3,"(iv) sets a date by which a proponent of a plan, other than the debtor, shall solicit acceptances of such plan;"],[3,"(v) fixes the scope and format of the notice to be provided regarding the hearing on approval of the disclosure statement; or"],[3,"(vi) provides that the hearing on approval of the disclosure statement may be combined with the hearing on confirmation of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/105?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§105. Power of court","tname":"Bankruptcy","by":{"3":"23"}},{"t":"usc","label":"11 U.S.C. § 330","url":"https://www.law.cornell.edu/uscode/text/11/330","by":{"3":"4"}},{"t":"usc","label":"11 U.S.C. § 707","url":"https://www.law.cornell.edu/uscode/text/11/707","by":{"3":"4"}},{"t":"usc","label":"11 U.S.C. § 1124","url":"https://www.law.cornell.edu/uscode/text/11/1124","ar":1,"by":{"3":"22"}},{"t":"usc","label":"28 U.S.C. § 2075","url":"https://www.law.cornell.edu/uscode/text/28/2075","by":{"3":"8"}}]};